/* Six-guide relay audio tour (generated by build_app_data.py from script.json; do not edit by hand).
   Voices are stock synthetic xAI TTS voices; the six guides are fictional characters, not real people.
   v = the 3 voices recorded for a segment, d = average clip length in seconds. Audio: audio/tour/s, audio/tour/h. */
window.TRIP_RELAY = {"base":"audio/tour/","voices":{"ara":{"name":"아라","color":"#d9822b"},"eve":{"name":"이브","color":"#c2185b"},"orion":{"name":"오리온","color":"#3949ab"},"lux":{"name":"럭스","color":"#2e7d32"},"luna":{"name":"루나","color":"#7e57c2"},"sal":{"name":"샐리","color":"#00838f"}},"hand":{"intro":{"ara":"안녕하세요, 아라예요. 오늘 두 분 산책의 따뜻한 수다는 제가 맡을게요.","eve":"하이, 이브예요! 오늘 텐션 담당은 저니까, 졸리면 언제든 불러 주세요.","orion":"오리온입니다. 두 분의 오늘 하루, 한 편의 영화로 만들어 드리죠.","lux":"럭스예요. 서두르지 않아도 다 보여요. 천천히 가요.","luna":"루나예요. 두 손 꼭 잡고, 편안하게 들어 주세요.","sal":"샐리예요. 길지도 짧지도 않게, 딱 좋은 만큼만 들려 드릴게요."},"tease":{"ara":{"eve":"이브 따라 뛰느라 숨찼죠? 아라랑은 손잡고 천천히 걸어요.","orion":"오리온 목소리에 깜짝 놀란 마음, 아라가 살살 달래 드릴게요.","lux":"럭스는 명언 제조기라니까요. 아라는 그냥 다정한 수다로 승부할게요.","luna":"루나가 다정하다고요? 다정함의 원조는 아라거든요.","sal":"샐리는 너무 매끄러워서 귀에 걸리는 게 없죠. 아라는 마음에 걸리게 말해 볼게요."},"eve":{"ara":"아라가 몸을 녹여 놨으니, 이브는 텐션을 데울게요. 러블리!","orion":"오리온, 예고편은 거기까지! 본편은 이브가 신나게 틀어 드려요.","lux":"럭스 얘기 듣다가 홍차 한 잔 다 우렸네요. 이브가 얼른 깨워 드릴게요!","luna":"루나 목소리가 너무 포근해서 두 분 졸까 봐 이브가 출동했어요!","sal":"샐리가 너무 매끈해서 미끄러질 뻔했어요. 이브는 브레이크 대신 액셀이에요!"},"orion":{"ara":"아라의 따뜻한 1막이 끝나고, 이제 오리온의 장엄한 2막이 열립니다.","eve":"이브가 폭풍처럼 지나간 자리, 그 고요 속에서 오리온이 등장합니다.","lux":"럭스의 지혜는 잔잔했죠. 오리온의 목소리엔 오케스트라가 깔립니다, 마음속에서요.","luna":"루나가 자장가였다면, 오리온은 블록버스터입니다. 팝콘 준비되셨죠?","sal":"샐리가 지킨 균형, 오리온이 아주 극적으로 깨 드리겠습니다."},"lux":{"ara":"아라가 마음을 데워 놨으니, 럭스는 거기에 생각 한 스푼만 넣을게요.","eve":"이브, 숨 쉬는 거 잊지 마세요. 럭스는 천천히, 대신 오래 기억나게 할게요.","orion":"오리온의 천둥 다음엔 잔잔한 바람이 어울리죠. 럭스예요.","luna":"루나만큼 다정하긴 어렵지만, 오래 들어도 안 질리는 건 럭스예요.","sal":"샐리랑 저, 둘 다 차분하단 말 듣죠. 그래도 깊이는 럭스가 한 뼘 더 깊어요."},"luna":{"ara":"아라가 이불을 깔아 줬으니, 루나는 베개를 놓아 드릴게요.","eve":"이브 따라 심장 쿵쾅거렸죠? 루나랑은 숨 한 번 고르고 들어요.","orion":"오리온 때문에 놀라신 분, 루나 쪽으로 오세요. 여긴 하나도 안 무서워요.","lux":"럭스 말이 조금 어려웠죠? 루나가 쉬운 말로 살살 풀어 볼게요.","sal":"샐리 설명도 좋았지만, 다정함 점수는 루나가 조금 더 받을 거예요."},"sal":{"ara":"아라 덕분에 분위기가 훈훈하죠? 샐리는 온도만 딱 맞출게요.","eve":"이브가 하늘까지 올린 텐션, 샐리가 부드럽게 착륙시켜 드릴게요.","orion":"오리온한테 박수 칠 뻔했죠? 샐리는 자막 없이도 쏙 들어오게 갈게요.","lux":"럭스가 철학 수업을 했으니, 샐리는 핵심만 군더더기 없이.","luna":"루나보단 제가 더 잘 설명할 거예요. 샐리 버전, 한번 비교해 보세요."}},"fallback":{"ara":["아라 왔어요. 이 얘기, 제가 제일 좋아하는 거예요.","아라예요. 두 분, 다리 아프면 꼭 말해요."],"eve":["이브 등판! 졸던 분 계시면 지금 깨어나세요.","이브예요. 이 얘기 진짜 재밌어요, 들어 보세요!"],"orion":["오리온입니다. 귀를 기울이세요, 역사가 속삭입니다.","다시 오리온입니다. 조명, 준비됐죠?"],"lux":["럭스예요. 잠깐 멈춰서 주변을 한번 둘러봐요.","럭스예요. 이 얘긴 천천히 들을수록 좋아요."],"luna":["루나예요. 춥지 않죠? 가까이 붙어서 들어요.","루나 왔어요. 편하게, 천천히요."],"sal":["샐리예요. 깔끔하게, 딱 필요한 만큼만.","샐리 차례예요. 군더더기 없이 갈게요."]}},"tours":{"vienna-city":{"start":[{"id":"r-city-intro","text":"오늘은 카를스플라츠에서 출발해 구시가지를 천천히 걷고, 트램을 타고 벨베데레까지 가요. 오늘 걷는 거리는 모두 합쳐 약 4킬로미터예요.","v":["eve","luna","sal"],"d":11.0}],"end":[{"id":"r-city-end","text":"카를스플라츠에서 벨베데레까지, 구시가지 열세 곳을 걸었어요. 다리는 좀 아파도 오늘 본 것들은 오래 기억날 거예요. 수고했어요!","v":["orion","lux","luna"],"d":10.2}],"stops":{"opernpassage":[{"id":"r-opernpassage-1","text":"여기는 카를스플라츠 지하의 오페른파사주예요. 지하철 U1, U2, U4가 만나는 곳이라 오늘 산책의 출발점으로 딱 좋아요. '오퍼' 출구로 올라가면 바로 오페라 극장이 반겨 줄 거예요.","v":["ara","orion","lux"],"d":15.0}],"staatsoper":[{"id":"r-staatsoper-1","text":"자, 고개를 들어 보세요. 지금 앞에 있는 건물이 빈 국립 오페라 극장이에요. 옛 성벽을 허문 자리에 링슈트라세라는 큰길이 생겼는데, 이 극장이 그 길에 처음 들어선 큰 건물이에요.","v":["ara","luna","sal"],"d":14.4},{"id":"r-staatsoper-2","text":"1869년 5월 25일, 프란츠 요제프 황제와 엘리자베트 황후가 지켜보는 가운데 모차르트의 〈돈 조반니〉로 문을 열었어요. 그런데 처음엔 평이 좋지 않았대요. 공사 도중 앞길이 1미터쯤 높아지는 바람에 '가라앉은 보물 상자' 같다는 놀림을 받았거든요.","v":["eve","orion","lux"],"d":20.4},{"id":"r-staatsoper-5","text":"놀림은 그걸로 끝나지 않았어요. 1866년 오스트리아가 크게 진 쾨니히그레츠 전투에 빗대 '건축의 쾨니히그레츠'라고까지 불렸대요. 돌이 워낙 많이 필요해서, 부다페스트에서 즐겨 쓰던 헝가리 쇼시쿠트 돌까지 실어 왔어요.","v":["ara","luna","sal"],"d":18.1},{"id":"r-staatsoper-3","text":"설계한 두 건축가 판 데어 뉠과 지카르츠부르크는 안타깝게도 1868년에 세상을 떠나, 끝내 완공을 보지 못했어요. 1945년 3월 12일 폭격으로 객석과 무대는 불탔지만, 미리 벽으로 막아 둔 앞부분은 살아남았어요. 모리츠 폰 슈빈트의 프레스코가 있는 로비와 큰 계단이 그때 그대로예요.","v":["orion","luna","sal"],"d":24.7},{"id":"r-staatsoper-6","text":"그날 불길에 120편이 넘는 오페라의 무대 장치와 의상 약 15만 벌도 함께 사라졌어요. 극장을 다시 지을 때 빈 시장은 거리 곳곳에 동전만 넣는 모금함을 놓았대요. 시민 누구나 이 극장의 주인이라고 자부할 수 있게요.","v":["eve","orion","lux"],"d":17.0},{"id":"r-staatsoper-4","text":"그리고 1955년 11월 5일, 베토벤의 〈피델리오〉로 다시 문을 열었어요. 같은 해 5월에는 오후에 갈 벨베데레에서 국가조약이 서명됐으니, 빈 사람들에겐 정말 특별한 한 해였죠.","v":["ara","eve","lux"],"d":14.9},{"id":"r-staatsoper-7","text":"그날 지휘봉은 카를 뵘이 잡았고, 오스트리아 방송 ORF는 이 공연으로 첫 생중계를 했어요. 그런데 그때 오스트리아 전체 텔레비전 시청자가 고작 800명쯤이었대요. 텔레비전이 그만큼 귀하던 시절이었어요.","v":["orion","luna","sal"],"d":16.5},{"id":"r-staatsoper-8","text":"1897년부터 10년 동안은 구스타프 말러가 이 극장을 이끌었어요. 공연 중에 객석 조명을 어둡게 한 것도 말러였는데, 처음엔 관객들이 꽤 싫어했대요. 지금은 너무 당연한 일이 됐죠.","v":["ara","eve","lux"],"d":15.3},{"id":"r-staatsoper-9","text":"지금도 이 극장은 1년에 오페라 50편에서 60편, 발레 열 편을 350번 넘게 무대에 올려요. 거의 매일 다른 작품이 올라가는 셈이에요. 빈 필하모닉 단원들도 바로 이 극장 오케스트라에서 뽑혀요.","v":["eve","orion","sal"],"d":15.3},{"id":"r-staatsoper-10","text":"해마다 사육제의 마지막 목요일 밤에는 이 극장이 통째로 무도회장이 되는 빈 오페라 무도회가 열려요. 오늘은 무도회가 없지만, 극장 앞에서 왈츠 한 스텝 정도는 괜찮잖아요.","v":["ara","lux","luna"],"d":13.4}],"cafe-sacher":[{"id":"r-cafe-sacher-1","text":"1832년, 메테르니히가 손님들을 위한 디저트를 주문했는데, 그걸 만든 사람이 열다섯이나 열여섯 살 견습생 프란츠 자허였다고 전해져요. 지금 카페 자허에서 드시는 바로 그 자허토르테예요.","v":["eve","orion","lux"],"d":15.6},{"id":"r-cafe-sacher-2","text":"다만 전해 오는 이야기예요. 자허 본인은 아흔 살 무렵, 1840년대 지금의 브라티슬라바인 프레스부르크에서 만들었다고 말하기도 했거든요. 정확한 기록은 남아 있지 않아요.","v":["ara","luna","sal"],"d":13.4},{"id":"r-cafe-sacher-3","text":"재미있는 건, 아들 에두아르트가 어제 갔던 데멜에서 견습생으로 일했다는 거예요. 1873년 케른트너 거리에 첫 식당을 열었고, 1876년 오페라 극장 맞은편에 호텔 자허를 열면서 자허토르테를 메뉴에 올렸어요.","v":["orion","luna","sal"],"d":18.4},{"id":"r-cafe-sacher-4","text":"호텔 자리는 원래 케른트너토어 극장이 있던 곳이에요. 1824년 5월 7일, 베토벤의 교향곡 9번이 처음 연주된 극장이죠. 바로 옆에 새 오페라 극장이 완공되자 1870년에 헐렸어요.","v":["ara","eve","lux"],"d":16.3},{"id":"r-cafe-sacher-5","text":"1892년 에두아르트가 세상을 떠난 뒤엔 아내 안나 자허가 호텔을 이끌었어요. 시가를 물고 프렌치 불도그를 데리고 다니는 걸로 유명했는데, 그 시절 호텔 자허는 귀족과 외교관이 모이는 곳이 됐어요.","v":["eve","orion","luna"],"d":15.5},{"id":"r-cafe-sacher-6","text":"1930년대에 호텔이 어려워지자, 에두아르트와 안나의 아들이 조리법을 데멜에 넘겼어요. 그때부터 두 집은 '원조' 이름을 두고 다퉜고, 시트를 두 겹으로 하느냐 한 겹으로 하느냐까지 따졌대요.","v":["ara","lux","sal"],"d":14.5},{"id":"r-cafe-sacher-7","text":"긴 다툼은 1963년에 끝났어요. 그 뒤로 호텔은 '오리지널 자허토르테', 데멜은 '데멜의 자허토르테'라는 이름으로 팔아요. 케이크 위 초콜릿 도장도 달라서, 호텔은 동그라미, 데멜은 세모예요.","v":["ara","eve","sal"],"d":16.3},{"id":"r-cafe-sacher-8","text":"전쟁 뒤 빈이 네 나라에 나뉘어 있던 시절엔 영국군이 이 호텔을 본부로 썼어요. 영화 〈제3의 사나이〉 각본을 쓴 그레이엄 그린도 호텔 바의 단골이었대요. 1969년엔 존 레논과 오노 요코가 여기서 기자회견을 열었어요.","v":["orion","lux","luna"],"d":18.3},{"id":"r-cafe-sacher-9","text":"한 입 잘라 보면 초콜릿 시트 사이로 살구잼이 보여요. 꽤 진해서, 빈에서는 달지 않은 생크림 슐라크를 곁들여 먹어요. 호텔 자허의 전 사장은 샴페인과 함께 먹기를 권했대요.","v":["orion","lux","sal"],"d":13.4},{"id":"r-cafe-sacher-10","text":"재미있게도 프랑스에서는 너무 달다는 평을, 미국에서는 좀 퍽퍽하다는 평을 듣는대요. 두 분 입맛에는 어떤지, 한 입씩 먹고 서로 점수를 매겨 봐요.","v":["ara","eve","luna"],"d":11.9}],"albertina":[{"id":"r-albertina-1","text":"알베르티나는 마리아 테레지아의 사위 알베르트 공작의 수집품에서 시작된 미술관이에요. 드로잉 약 6만 5천 점, 판화 약 100만 점을 가진 세계적인 판화실이에요.","v":["ara","orion","luna"],"d":12.7},{"id":"r-albertina-2","text":"테라스에서 광장 건너편을 보세요. 1945년 3월 12일 폭격으로 수백 명이 숨진 필립호프 자리예요. 1988년 그곳에 흐르들리치카의 〈전쟁과 파시즘에 반대하는 기념비〉가 세워졌어요.","v":["eve","lux","sal"],"d":15.8}],"hofburg":[{"id":"r-hofburg-1","text":"호프부르크는 13세기에 처음 지어져, 합스부르크 가문이 수백 년 동안 겨울을 보낸 궁전이에요. 지나가는 스위스 궁정에는 신성로마제국 황제관과 오스트리아 제국 황관을 보관한 왕실 보물관이 있어요. 새로 꾸민 시시 박물관은 2026년 11월 19일에 다시 문을 열었지만, 오늘은 바깥만 보고 지나가요.","v":["orion","lux","sal"],"d":23.6}],"hofreitschule":[{"id":"r-hofreitschule-1","text":"스페인 승마학교는 1565년 기록에 처음 나오는, 이런 학교 가운데 가장 오래된 곳이에요. 공연장인 하얀 겨울 승마장은 1729년부터 1735년까지 요제프 에마누엘 피셔 폰 에를라흐가 지었어요.","v":["ara","eve","luna"],"d":18.3},{"id":"r-hofreitschule-2","text":"하얀 리피차너도 태어날 땐 갈색이나 검은색이고, 여섯 살에서 열 살쯤 되어야 하얘진대요. 오늘 혹시 마주치면 나이를 한번 짐작해 봐요.","v":["eve","orion","sal"],"d":10.6}],"michaelerplatz":[{"id":"r-michaelerplatz-1","text":"광장 가운데 유리 너머 유적은 로마 군단 기지 빈도보나 바깥 마을의 집터예요. 맞은편의 장식 없는 건물은 아돌프 로스의 로스하우스로, 1912년 완공 무렵 큰 논란이 됐어요.","v":["ara","lux","luna"],"d":14.8},{"id":"r-michaelerplatz-2","text":"옆 미하엘 성당에서는 1791년 12월 10일, 모차르트 추모 미사 때 〈레퀴엠〉 일부가 처음 연주됐어요. 모차르트가 세상을 떠나고 닷새 뒤였어요.","v":["eve","lux","luna"],"d":12.8}],"demel":[{"id":"r-demel-1","text":"콜마르크트에는 18세기에 젊은 하이든이 살았고, 쇼팽도 1830년부터 1831년까지 이 거리에 머물렀어요. 14번지 데멜은 1786년에 문을 연 황실 납품 제과점으로, 어제 카이저슈마렌을 먹은 곳이에요.","v":["ara","orion","sal"],"d":18.7}],"graben":[{"id":"r-graben-1","text":"그라벤은 '도랑'이라는 뜻으로, 로마 시대 성벽 앞 도랑 자리에서 시작된 거리예요. 가운데 페스트 기둥은 1679년 흑사병 때 레오폴트 1세가 한 서원으로 세워져 1693년에 봉헌됐어요. 기둥 아래 무릎 꿇은 황제도 찾아보세요.","v":["ara","lux","luna"],"d":19.7}],"peterskirche":[{"id":"r-peterskirche-1","text":"성 페터 성당은 1733년에 봉헌된, 빈 바로크에서 처음으로 돔을 올린 성당이에요. 돔 천장의 〈성모 대관〉은 로트마이어가 그렸어요. 미사 중이면 뒤쪽에서 조용히 봐요.","v":["eve","orion","sal"],"d":14.9}],"stephansdom":[{"id":"r-stephansdom-1","text":"고개를 끝까지 젖혀 보세요. 슈테판 대성당의 저 뾰족한 남탑은 높이 136미터, 1433년에 완성됐어요. 이 자리에 첫 성당이 봉헌된 건 1147년인데, 제2차 십자군 원정을 떠나려던 콘라트 3세도 그 자리에 있었대요.","v":["orion","lux","sal"],"d":19.6},{"id":"r-stephansdom-5","text":"빈 사람들은 이 남탑을 '슈테플', 그러니까 꼬마 슈테판이라고 다정하게 불러요. 1529년과 1683년 오스만 군대가 빈을 에워쌌을 땐 도시를 지키는 지휘소였어요. 1955년까지는 밤마다 망루지기가 올라가, 불이 보이면 종을 울렸대요.","v":["ara","eve","sal"],"d":21.3},{"id":"r-stephansdom-6","text":"반대편 북탑은 남탑만큼 올리려다 1511년에 공사를 멈춰서 68미터에 그쳤어요. 대신 그 안에 오스트리아에서 가장 큰 종, 2만 킬로그램이 넘는 품메린이 걸려 있어요. 새해 첫날이나 부활절 같은 특별한 날에만 울려요.","v":["orion","lux","luna"],"d":17.8},{"id":"r-stephansdom-2","text":"이제 지붕을 보세요. 유약 바른 기와 약 23만 장으로 덮여 있고, 남쪽 면에는 쌍두독수리 무늬가 있어요. 1945년 4월 12일, 근처 상점에서 난 불이 옮겨붙어 지붕이 무너졌어요. 지금 보는 지붕은 전쟁 뒤에 다시 올린 거예요.","v":["ara","eve","luna"],"d":19.3},{"id":"r-stephansdom-7","text":"그 불이 나기 직전에도 위기가 있었어요. 물러나던 독일군 쪽에서 대성당에 포탄 백 발을 쏘라는 명령이 내려왔는데, 게르하르트 클링키히트 대위가 그 명령을 따르지 않았대요. 덕분에 성당은 포격을 피했어요.","v":["ara","orion","luna"],"d":16.3},{"id":"r-stephansdom-8","text":"북쪽 지붕에는 빈시와 오스트리아 공화국의 문장이 있어요. 지붕이 워낙 가팔라서 빗물만으로 깨끗이 씻기고, 눈도 잘 쌓이지 않는대요. 다시 지을 때는 나무 대신 강철 600톤 넘게 써서 뼈대를 짰어요.","v":["eve","lux","sal"],"d":16.0},{"id":"r-stephansdom-3","text":"모차르트는 1782년 8월 4일 이곳에서 콘스탄체와 결혼했어요. 근처 피가로 하우스에 살 때 여기가 그의 본당이었고, 세상을 떠나기 얼마 전에는 대성당 부악장으로 임명되기도 했어요.","v":["eve","orion","sal"],"d":15.8},{"id":"r-stephansdom-9","text":"1791년 12월 6일, 모차르트의 장례 예배도 이 성당의 십자가 예배당에서 치러졌어요. 하이든은 어린 시절 이 성당 소년 합창단원이었고, 1760년에 여기서 결혼했어요. 1741년 비발디의 장례식도 이곳에서 열렸고요.","v":["eve","luna","sal"],"d":18.8},{"id":"r-stephansdom-10","text":"안에 들어가면 돌로 된 설교단 아래를 찾아보세요. 창문 밖으로 고개를 내민 얼굴 조각이 있는데, '창밖을 엿보는 사람'이라는 뜻의 펜스터구커예요. 조각가 자신의 모습일 거라고들 해요. 계단 난간에는 서로 물어뜯는 두꺼비와 도마뱀도 있어요.","v":["ara","orion","lux"],"d":18.8},{"id":"r-stephansdom-4","text":"일요일 관광 관람은 오후 1시부터 4시 반까지라, 이제 들어가면 돼요. 입구 쪽 뒷부분은 무료예요. 안에서는 목소리를 낮추고 천천히 한 바퀴 돌아봐요.","v":["ara","lux","luna"],"d":12.3}],"bitzinger":[{"id":"r-bitzinger-1","text":"오페라 극장 뒤 비칭어 소시지 가판, 점심으로 딱이에요. 빈의 소시지 가판 문화는 2024년 오스트리아 무형문화유산 목록에 올랐어요. 치즈가 든 케제크라이너 하나 사서 나눠 먹어요.","v":["orion","lux","luna"],"d":14.5}],"tram-oper":[{"id":"r-tram-oper-1","text":"여기서 트램 D, 압스베르크가세 방면을 타요. 네 번째 정류장 슐로스 벨베데레에서 내리면 돼요. 시간표상 약 9분 걸려요.","v":["ara","eve","sal"],"d":10.1}]},"bytes":12048096},"belvedere":{"start":[{"id":"r-belvedere-1","text":"벨베데레는 오스만 전쟁의 영웅 오이겐 공의 여름 궁전으로, 요한 루카스 폰 힐데브란트가 설계했어요. 손님을 맞던 상궁은 1723년에 완성됐어요. 정원 쪽에서 돌아보면 빈 시내가 내려다보여요.","v":["ara","eve","sal"],"d":16.7},{"id":"r-belvedere-2","text":"박물관은 층을 에베네 0, 1, 2로 표기해요. 한국식으로는 1층, 2층, 3층이에요. 전시 배치는 바뀔 수 있으니 입구 안내도를 먼저 확인해요. 〈키스〉 방이 가장 붐비니 먼저 가도 좋아요.","v":["ara","eve","lux"],"d":15.2}],"end":[{"id":"r-belvedere-end","text":"오늘 벨베데레에서 본 그림 중 어떤 게 제일 마음에 남았는지, 숙소까지 천천히 걸으며 서로 이야기해 봐요.","v":["ara","orion","sal"],"d":7.7}],"stops":{"a-marmorsaal":[{"id":"r-marmorsaal-1","text":"여기는 대리석 홀이에요. 1955년 5월 15일 이 홀에서 오스트리아 국가조약이 서명됐어요. 피글 외무장관이 발코니에서 조약서를 들어 보이던 곳이에요. 천장화는 카를로 카를로네가 그렸어요.","v":["orion","luna","sal"],"d":15.9}],"a-messerschmidt":[{"id":"r-messerschmidt-1","text":"프란츠 크사버 메서슈미트의 성격 두상이에요. 얼굴을 잔뜩 찡그린 두상들인데, 제목은 작가가 죽은 뒤에 붙었어요. 마음 가는 대로 표정을 읽어 보고, 서로 하나씩 따라 해 봐요.","v":["eve","luna","sal"],"d":13.5}],"a-napoleon":[{"id":"r-napoleon-1","text":"자크루이 다비드의 〈그랑 생베르나르 고개를 넘는 나폴레옹〉이에요. 다섯 점 연작 중 하나로, 1834년부터 벨베데레에 있어요. 실제로는 맑은 날 노새를 타고 넘었지만, 나폴레옹은 '사나운 말 위의 침착한 모습'을 원했대요.","v":["ara","orion","lux"],"d":18.2}],"a-waldmueller":[{"id":"r-waldmueller-1","text":"페르디난트 게오르크 발트뮐러의 〈성체축일 아침〉, 1857년 작품이에요. 축제날 아침의 환한 햇살 속에 가난한 사람들의 모습도 함께 담았어요.","v":["ara","lux","sal"],"d":12.2}],"a-judith":[{"id":"r-judith-1","text":"구스타프 클림트의 〈유디트 1〉, 1901년 작품이에요. 클림트 그림에서 금이 처음으로 주인공처럼 쓰인 작품이에요.","v":["eve","orion","luna"],"d":8.9}],"a-kiss":[{"id":"r-kiss-1","text":"이 방에서 사람이 제일 많이 모인 그림, 클림트의 〈키스〉예요. 1908년 쿤스트샤우 전시에 '연인'이라는 제목으로 처음 걸렸어요. 프란츠 요제프 황제 즉위 60주년에 맞춰 열린 전시였어요.","v":["ara","eve","sal"],"d":15.2},{"id":"r-kiss-5","text":"사실 그때 그림은 아직 덜 끝난 상태였어요. 전시 중에 찍은 사진을 보면 왼쪽 아래 구석이 비어 있대요. 클림트는 이듬해 여름까지 꽃과 옷 무늬를 다듬고, 무릎 꿇은 여자의 종아리도 조금 더 길게 고쳤어요.","v":["orion","lux","luna"],"d":16.2},{"id":"r-kiss-2","text":"그런데도 전시가 열린 지 열흘 만인 1908년 7월 10일, 국가가 이 그림을 사들이기로 했어요. 프라하의 미술관도 탐을 내고 있어서 서둘렀던 것 같대요. 그만큼 반응이 뜨거웠던 거죠.","v":["ara","luna","sal"],"d":14.3},{"id":"r-kiss-6","text":"값은 2만 5천 크로네였어요. 그 두 배도 안 되는 돈이면 잘츠카머구트에 가구까지 딸린 별장 한 채를 살 수 있던 시절이었대요. 그때까지 이 미술관이 살아 있는 화가의 그림에 낸 값 가운데 가장 비쌌어요.","v":["eve","orion","lux"],"d":15.6},{"id":"r-kiss-7","text":"불과 몇 년 전 클림트는 빈 대학 천장화로 '외설'이라는 비난까지 받고 공공 주문에서 물러나 있었어요. 이 그림 한 점으로 분위기가 확 바뀐 셈이에요. 이 미술관의 전신인 현대 미술관도 1903년 클림트 같은 화가들이 앞장서서 만든 곳이에요.","v":["eve","orion","luna"],"d":19.8},{"id":"r-kiss-3","text":"180센티미터 정사각형 캔버스에 금박과 은, 백금을 썼어요. 1903년 이탈리아 라벤나에서 본 비잔틴 모자이크에서 영감을 받았대요. 아버지가 금 조각 장인이었으니, 금과는 원래 인연이 깊었던 셈이죠.","v":["ara","lux","sal"],"d":16.8},{"id":"r-kiss-8","text":"남자의 머리가 캔버스 위쪽 끝에 거의 닿아 있죠. 이렇게 화면을 꽉 채운 구도는 일본 판화의 영향으로 봐요. 남자는 덩굴 관을, 여자는 꽃 관을 썼고, 남자 얼굴은 숨긴 채 눈을 감은 여자 얼굴만 우리 쪽을 향해 있어요.","v":["ara","eve","luna"],"d":17.4},{"id":"r-kiss-4","text":"가까이 가서 옷을 보세요. 남자 옷은 네모난 무늬, 여자 옷은 꽃무늬예요. 두 사람은 꽃이 핀 풀밭 끝자락에 있고, 여자의 발끝 바로 아래에서 풀밭이 끝나요.","v":["orion","lux","sal"],"d":12.7},{"id":"r-kiss-9","text":"모델이 클림트 자신과, 평생 곁에 있던 패션 디자이너 에밀리 플뢰게라는 이야기도 있지만 증거는 없어요. 신화 속 아폴론과 다프네, 오르페우스와 에우리디케를 그렸다는 해석도 있고요. 두 분은 누구라고 생각해요?","v":["ara","eve","lux"],"d":16.5}],"a-vangogh":[{"id":"r-vangogh-1","text":"빈센트 반 고흐의 〈오베르의 평원〉이에요. 1890년, 반 고흐가 생애 마지막 여름에 오베르에서 그린 넓은 들판이에요.","v":["orion","luna","sal"],"d":10.2}],"a-tod-maedchen":[{"id":"r-tod-maedchen-1","text":"에곤 실레의 〈죽음과 소녀〉예요. 가로 180센티미터의 큰 그림이에요. 실레는 처음에 이 그림을 '남자와 소녀', '얽힌 사람들'이라고 불렀대요.","v":["ara","eve","lux"],"d":11.8},{"id":"r-tod-maedchen-5","text":"그림 속 남자는 실레 자신의 자화상이고, 두 팔로 꼭 매달린 여자는 오랜 연인이자 모델이었던 발리 노이칠이에요. 남자의 눈은 여자가 아니라 허공을 보고 있어요.","v":["orion","luna","sal"],"d":13.0},{"id":"r-tod-maedchen-2","text":"1911년, 스물한 살 실레는 열일곱 살 발리를 만났어요. 둘은 함께 살았고, 발리는 〈발리의 초상〉을 비롯해 실레의 유명한 그림 여러 점에 모델이 되어 줬어요.","v":["ara","eve","sal"],"d":12.6},{"id":"r-tod-maedchen-6","text":"1912년 실레가 노이렝바흐에서 체포돼 24일 동안 갇혔을 때도, 끝까지 곁을 지킨 사람은 발리였다고 실레가 직접 적었어요.","v":["orion","lux","luna"],"d":10.5},{"id":"r-tod-maedchen-7","text":"1914년, 실레는 빈 히칭의 작업실 맞은편에 사는 하름스 자매를 만났어요. 그리고 친구에게 보낸 편지에 '결혼할 생각이다, 유리하게, 발리 말고'라고 썼대요.","v":["ara","orion","lux"],"d":13.0},{"id":"r-tod-maedchen-8","text":"1915년, 실레는 카페에서 발리에게 에디트와 결혼하겠다고 알렸어요. 발리는 그 자리에서 관계를 끝냈고, 두 사람은 다시는 만나지 않았어요. 그해 실레는 에디트와 결혼했고, 사흘 뒤 군에 소집됐어요.","v":["eve","luna","sal"],"d":16.4},{"id":"r-tod-maedchen-3","text":"그래서 이 그림을 발리와의 이별로 읽는 사람이 많아요. 수도복 차림의 남자가 죽음, 그를 붙든 여자가 소녀예요. 두 사람 자세가 불안하게 기울어 있죠. 곧 깨질 것 같은 균형이에요. 두 손은 잡고 있는 걸까요, 놓으려는 걸까요.","v":["ara","orion","luna"],"d":17.0},{"id":"r-tod-maedchen-9","text":"아까 본 〈키스〉가 떠오르지 않나요? 껴안은 두 사람이라는 구도는 닮았지만, 실레는 금빛 대신 탁한 색과 날카로운 선으로 그렸어요. 스승처럼 따르던 클림트와 실레가 얼마나 다른지 잘 보이는 그림이에요.","v":["eve","lux","sal"],"d":15.6},{"id":"r-tod-maedchen-10","text":"발리는 이별 뒤 간호사가 되어 전쟁 중 병원에서 일했어요. 그리고 1917년 크리스마스에 달마티아에서 성홍열로 세상을 떠났어요. 스물셋이었어요.","v":["ara","lux","sal"],"d":12.4},{"id":"r-tod-maedchen-4","text":"1918년 2월 클림트가 세상을 떠났고, 그해 가을 스페인 독감이 빈을 덮쳤어요. 임신 6개월이던 에디트가 10월 28일에 숨졌고, 실레도 사흘 뒤 스물여덟 살로 세상을 떠났어요. 같은 층의 〈가족〉이 그 마지막 해의 그림이에요.","v":["eve","orion","luna"],"d":18.8}],"a-familie":[{"id":"r-familie-1","text":"에곤 실레의 〈가족〉, 1918년 작품이에요. 실레가 스물여덟에 스페인 독감으로 세상을 떠나기 직전 그린 그림이에요. '가족'이라는 제목은 나중에 붙어서, 모델이 실레 가족이라고 단정할 수는 없어요.","v":["ara","eve","sal"],"d":15.2}],"a-znaim":[{"id":"r-znaim-1","text":"빈 공방이 1440년에서 1450년 무렵 만든 츠나임 제단이에요. 높이 약 5미터의 날개 제단으로, 금박 조각과 채색이 거의 그대로 남아 있어요.","v":["orion","lux","luna"],"d":12.0}]},"bytes":7672536}}};
